PRAGMA foreign_keys=ON;
CREATE TABLE Usuario(id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL,email TEXT NOT NULL UNIQUE,senha TEXT NOT NULL);
CREATE TABLE Encomenda(id INTEGER PRIMARY KEY AUTOINCREMENT,cliente TEXT NOT NULL,endereco TEXT NOT NULL,numero TEXT NOT NULL,cidade TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Pendente');
CREATE TABLE Rota(id INTEGER PRIMARY KEY AUTOINCREMENT,ponto_partida TEXT NOT NULL,ponto_chegada TEXT NOT NULL,data_criacao TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE Rota_Encomenda(rota_id INTEGER NOT NULL,encomenda_id INTEGER NOT NULL,PRIMARY KEY(rota_id,encomenda_id),FOREIGN KEY(rota_id) REFERENCES Rota(id) ON DELETE CASCADE,FOREIGN KEY(encomenda_id) REFERENCES Encomenda(id) ON DELETE CASCADE);
